CREATE OR REPLACE FUNCTION public.store_cambio_closed_record_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF OLD.tipo='cambio' AND OLD.estado IN ('entregado','cancelado','rechazado') AND (NEW.estado IS DISTINCT FROM OLD.estado OR NEW.comentario IS DISTINCT FROM OLD.comentario OR NEW.motivo_admin IS DISTINCT FROM OLD.motivo_admin OR NEW.motivo IS DISTINCT FROM OLD.motivo OR NEW.recibido_en IS DISTINCT FROM OLD.recibido_en OR NEW.recibido_por IS DISTINCT FROM OLD.recibido_por OR NEW.reemplazo_entregado_at IS DISTINCT FROM OLD.reemplazo_entregado_at OR NEW.reemplazo_estado IS DISTINCT FROM OLD.reemplazo_estado OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.compra_id IS DISTINCT FROM OLD.compra_id OR NEW.preorder_id IS DISTINCT FROM OLD.preorder_id OR NEW.order_item_id IS DISTINCT FROM OLD.order_item_id) THEN RAISE EXCEPTION 'Registro cerrado protegido: documentá la corrección sin reescribir datos ni reabrir operaciones'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER zzz_store_cambio_closed_record_guard BEFORE UPDATE ON public.store_cambios FOR EACH ROW EXECUTE FUNCTION public.store_cambio_closed_record_guard();
COMMENT ON FUNCTION public.store_cambio_closed_record_guard() IS 'Closed exchanges preserve original descriptions, receipt/operational state and order references; administrative corrections remain separately audited.';